StopMotionProject.ProjectCode:
from dataclasses import dataclass, field
# ── Walk / link parameters ───────────────────────────────────────────────────── WALK_PARAMS = { 'frame_interval': 0.01, 'phase_offset': 3.141592653589793, 'init_wait_time': 0.0, 'landing_period_ratio': 0.1, 'weight_shift_duration_ratio': 0.25, 'end_of_simulation': 8.0, 'cycle_duration': 1.1, 'swing_ratio': 0.4, 'foot_lift': 0.02, 'hip_swing': 0.015, 'lateral_swing_ratio_1st': 0.8, 'forward_stride': 0.005, 'duration': 5.0, 'forward_lean_angle': 10.0, 'shoulder_roll_angle': 10.0, 'arm_swing_angle': 20.0, 'smooth_stop': False, 'mix_enable': False, 'mix_gyro_g': 0.001, }
LINK_PARAMS = { 'HIPJOINT_ZY_TO_XR_OFFSET': 0.07, 'THIGH_LENGTH': 0.065, 'SHANK_LENGTH': 0.065, 'ANKLE_LENGTH': 0.04, 'ANKLE_TO_FOOT': 0.05, 'SHORTEN_LEG_LENGTH': 0.02, }
# ── User-tunable gait / stick feel (ProjectCode owns these) ─────────────────── # Stick range is -1..+1 (Meridim). Graph raw thresholds ≈ value * 127. STICK_DEAD = 0.12 # walk on/off (left stick Y) TURN_STICK_DEAD = 0.15 # turn bias on/off (right stick X) SIDE_STICK_THRESH = 90 / 127.0 # sidestep on/off (left stick X) MAX_FWD_STRIDE = 0.035 # [m] |fwd|=1 → this stride MAX_TURN_STRIDE = 0.02 # [m] added to L/R stride as yaw bias MAX_SIDE_STRIDE = 0.025 # [m] |lat|=1 → this lateral stride HIPJOINT_YP_WALK_OFFSET = -10.0 # [deg] extra hip pitch while walking ELBOW_BEND_WALK = 45.0 # [deg] default elbow; walk_ik_step may override
IDX_L_HIPJOINT_YP = 35; IDX_R_HIPJOINT_YP = 65 IDX_L_ANKLE_YP = 39; IDX_R_ANKLE_YP = 69 IDX_L_ANKLE_XR = 41; IDX_R_ANKLE_XR = 71
# ── WalkParams / LinkParams (owned by ProjectCode) ──────────────────────────── def _param_field(default, description, type_): return field(default=default, metadata={"description": description, "type": type_})
@dataclass class WalkParams: frame_interval: float = _param_field(0.010, "Fixed time step per frame [s]", "float") phase_offset: float = _param_field(3.141592653589793, "Phase offset [rad]", "float") init_wait_time: float = _param_field(0.0, "Initial wait time [s]", "float") landing_period_ratio: float = _param_field(0.10, "Both-feet landing period ratio", "float") weight_shift_duration_ratio: float = _param_field(0.25, "Weight-shift period ratio", "float") end_of_simulation: float = _param_field(8.0, "Simulation end time [s]", "float") cycle_duration: float = _param_field(1.1, "Gait cycle duration [s]", "float") swing_ratio: float = _param_field(0.4, "Swing phase ratio (0.0-1.0)", "float") foot_lift: float = _param_field(0.02, "Foot lift height [m]", "float") hip_swing: float = _param_field(0.015, "Lateral hip swing amplitude [m]", "float") lateral_swing_ratio_1st: float = _param_field(0.8, "Lateral swing multiplier", "float") forward_stride: float = _param_field(0.005, "Forward stride length [m]", "float") duration: float = _param_field(5.0, "Motion duration [s]", "float") forward_lean_angle: float = _param_field(10.0, "Forward lean angle [deg]", "float") shoulder_roll_angle: float = _param_field(10.0, "Shoulder roll angle [deg]", "float") arm_swing_angle: float = _param_field(20.0, "Arm swing amplitude [deg]", "float") smooth_stop: bool = _param_field(False, "Extra step before stopping", "bool") mix_enable: bool = _param_field(False, "Apply gyro roll mixing", "bool") mix_gyro_g: float = _param_field(0.001, "Gyro mixing gain", "float")
@dataclass class LinkParams: HIPJOINT_ZY_TO_XR_OFFSET: float = _param_field(0.07, "Yaw-to-roll hip offset [m]", "float") THIGH_LENGTH: float = _param_field(0.065, "Thigh length [m]", "float") SHANK_LENGTH: float = _param_field(0.065, "Shank length [m]", "float") ANKLE_LENGTH: float = _param_field(0.040, "Ankle-to-roll axis [m]", "float") ANKLE_TO_FOOT: float = _param_field(0.05, "Roll axis to sole [m]", "float") SHORTEN_LEG_LENGTH: float = _param_field(0.02, "Leg shortening [m]", "float")
@property def TOTAL_LEG_LENGTH(self): return self.THIGH_LENGTH + self.SHANK_LENGTH + self.ANKLE_LENGTH
@property def LINK_LEG_LENGTH(self): return self.THIGH_LENGTH + self.SHANK_LENGTH
def load_walk_params(): p = WalkParams() for k, v in globals().get('WALK_PARAMS', {}).items(): if hasattr(p, k): setattr(p, k, v) return p
def load_link_params(): p = LinkParams() for k, v in globals().get('LINK_PARAMS', {}).items(): if hasattr(p, k): setattr(p, k, v) return p
# ── WalkController ──────────────────────────────────────────────────────────── class WalkController: IDLE = 0 WALK = 1
def __init__(self, params=None, params_link=None, msg_size=90): self.params = params if params is not None else load_walk_params() self.params_link = params_link if params_link is not None else load_link_params() self.msg_size = msg_size self.mot_sts = self.IDLE self.w_sts = 0 self.t = 0 self.foot_ref_pitch = 0.0 self.trq_on = 1.0 self.stop_requested = False self.use_zero_stride = False self.stride_turn_bias = 0.0 self.data = [0.0] * msg_size self.buf_output = [] self.buf_input = [] self.buf_index = 0 self.background_thread = None self.stop_background = False
def calculate_foot_height(self, phase, step_height): normalized_phase = ((phase % (2 * math.pi)) + 2 * math.pi) % (2 * math.pi) swing_duration = self.params.swing_ratio * 2.0 * math.pi swing_start = math.pi - swing_duration / 2 swing_end = math.pi + swing_duration / 2 if swing_start <= normalized_phase <= swing_end: swing_phase = (normalized_phase - swing_start) / swing_duration return step_height * math.sin(swing_phase * math.pi) return 0.0
def calculate_forward_motion(self, phase, step_length): return step_length * math.sin(phase)
def apply_gyro_mixing(self, data, r): if not self.params.mix_enable: return g = self.params.mix_gyro_g gy = float(r.get('gy', 0.0)) * 100.0 gx = float(r.get('gx', 0.0)) * 100.0 pc = -gy * g data[IDX_L_ANKLE_YP] += pc; data[IDX_R_ANKLE_YP] += pc data[IDX_L_HIPJOINT_YP] += pc * 0.5; data[IDX_R_HIPJOINT_YP] += pc * 0.5 rc = gx * g data[IDX_L_ANKLE_XR] += rc data[IDX_R_ANKLE_XR] -= rc
def geometric_leg_ik(self, target_pos, target_roll=None, target_pitch=None, is_left=True): if np.linalg.norm(target_pos) > self.params_link.TOTAL_LEG_LENGTH: return None actual_leg_length = math.sqrt(target_pos[1]**2 + target_pos[2]**2) hip_roll = math.atan2(target_pos[1], actual_leg_length) MAX_ROLL = math.pi / 4 hip_roll = max(-MAX_ROLL, min(MAX_ROLL, hip_roll)) xz_proj = math.sqrt(target_pos[0]**2 + target_pos[2]**2) cos_knee = (self.params_link.THIGH_LENGTH**2 + self.params_link.SHANK_LENGTH**2 - xz_proj**2) / \ (2 * self.params_link.THIGH_LENGTH * self.params_link.SHANK_LENGTH) knee_pitch = math.pi - math.acos(max(-1.0, min(1.0, cos_knee))) if knee_pitch == 0.0: return None leg_angle = math.atan2(target_pos[0], target_pos[2]) thigh_pitch = leg_angle - knee_pitch / 2.0 ankle_pitch = -(leg_angle + knee_pitch / 2.0) ankle_roll = -hip_roll if target_roll is not None: corr = target_roll * 0.5 hip_roll = max(-MAX_ROLL, min(MAX_ROLL, hip_roll + corr)) ankle_roll = max(-MAX_ROLL, min(MAX_ROLL, ankle_roll - corr)) if target_pitch is not None: ankle_pitch += target_pitch return np.array([0.0, hip_roll, thigh_pitch, knee_pitch, ankle_pitch, ankle_roll])
def compute_walking_pose(self): p = self.params pl = self.params_link if self.w_sts == 0 or self.w_sts == 1: z = pl.LINK_LEG_LENGTH - pl.SHORTEN_LEG_LENGTH l_pos = np.array([0.0, 0.0, z]) r_pos = np.array([0.0, 0.0, z]) l_ang = self.geometric_leg_ik(l_pos, is_left=True) r_ang = self.geometric_leg_ik(r_pos, is_left=False) else: phase_y = 2 * math.pi * ((self.t - p.init_wait_time) / p.cycle_duration) phase_z = 2 * math.pi * ((self.t - (p.init_wait_time + p.cycle_duration * p.weight_shift_duration_ratio)) / p.cycle_duration) if self.w_sts == 2: lat = p.hip_swing * math.sin(phase_y) * p.lateral_swing_ratio_1st l_fw = r_fw = l_lift = r_lift = 0.0 else: norm_z = ((phase_z % (2 * math.pi)) + 2 * math.pi) % (2 * math.pi) at_start = norm_z < 0.3 * math.pi if p.smooth_stop: if self.stop_requested and not self.use_zero_stride and at_start: self.use_zero_stride = True else: if self.stop_requested and not self.use_zero_stride: self.use_zero_stride = True lat = p.hip_swing * math.sin(phase_y) l_lift = self.calculate_foot_height(phase_z, p.foot_lift) r_lift = self.calculate_foot_height(phase_z + p.phase_offset, p.foot_lift) if self.use_zero_stride: l_fw = r_fw = 0.0 else: l_fw = self.calculate_forward_motion(phase_z, p.forward_stride + self.stride_turn_bias) r_fw = self.calculate_forward_motion(phase_z + p.phase_offset, p.forward_stride - self.stride_turn_bias) z = pl.LINK_LEG_LENGTH - pl.SHORTEN_LEG_LENGTH l_pos = np.array([l_fw, -lat, z - l_lift]) r_pos = np.array([r_fw, lat, z - r_lift]) l_ang = self.geometric_leg_ik(l_pos, target_pitch=self.foot_ref_pitch, target_roll=0.0, is_left=True) r_ang = self.geometric_leg_ik(r_pos, target_pitch=self.foot_ref_pitch, target_roll=0.0, is_left=False) if self.w_sts == 3 and p.arm_swing_angle != 0.0: stride_sign = math.copysign(1.0, p.forward_stride) if p.forward_stride != 0.0 else 1.0 arm = p.arm_swing_angle * math.sin(phase_z) * stride_sign self.data[22] = float(self.trq_on); self.data[23] = -arm self.data[52] = float(self.trq_on); self.data[53] = arm if l_ang is not None and r_ang is not None: for i in range(6): self.data[30+2*i] = float(self.trq_on); self.data[31+2*i] = float(math.degrees(l_ang[i])) self.data[60+2*i] = float(self.trq_on); self.data[61+2*i] = float(math.degrees(r_ang[i])) if self.w_sts >= 2: if p.forward_lean_angle != 0.0: self.data[35] += p.forward_lean_angle self.data[65] += p.forward_lean_angle self.data[35] += HIPJOINT_YP_WALK_OFFSET self.data[65] += HIPJOINT_YP_WALK_OFFSET if self.w_sts >= 1: self.data[24] = float(self.trq_on); self.data[25] = float(p.shoulder_roll_angle) self.data[54] = float(self.trq_on); self.data[55] = float(p.shoulder_roll_angle) self.data[28] = float(self.trq_on); self.data[29] = -ELBOW_BEND_WALK self.data[58] = float(self.trq_on); self.data[59] = -ELBOW_BEND_WALK
def update_walking_state(self): p = self.params if self.t < p.init_wait_time: self.w_sts = 0 elif self.t < p.init_wait_time + p.cycle_duration * p.landing_period_ratio: self.w_sts = 1 elif self.t < p.init_wait_time + p.cycle_duration * p.weight_shift_duration_ratio: self.w_sts = 2 else: self.w_sts = 3
def start_walk(self): self.mot_sts = self.WALK self.data[20] = float(self.trq_on)
def stop_walk(self): self.mot_sts = self.IDLE z = self.params_link.LINK_LEG_LENGTH - self.params_link.SHORTEN_LEG_LENGTH la = self.geometric_leg_ik(np.array([0.0, 0.0, z]), is_left=True) ra = self.geometric_leg_ik(np.array([0.0, 0.0, z]), is_left=False) if la is not None and ra is not None: for i in range(6): self.data[30+2*i] = float(self.trq_on); self.data[31+2*i] = float(math.degrees(la[i])) self.data[60+2*i] = float(self.trq_on); self.data[61+2*i] = float(math.degrees(ra[i])) self.data[22] = float(self.trq_on); self.data[23] = 0.0 self.data[24] = float(self.trq_on); self.data[25] = 0.0 self.data[52] = float(self.trq_on); self.data[53] = 0.0 self.data[54] = float(self.trq_on); self.data[55] = 0.0
def stop(self): self.stop_walk()
@property def busy(self): return bool(self.stop_requested or self.use_zero_stride)
def reset_pose(self): self.mot_sts = self.IDLE for i in range(30): self.data[20+2*i] = float(self.trq_on) self.data[21+2*i] = 0.0
# ── Pad helper ──────────────────────────────────────────────────────────────── def _pad_axes(): if _bhv_commander is None: return 0.0, 0.0, 0.0 with _bhv_commander._pad_lock: pad = list(_bhv_commander._pad) if _bhv_commander._pad is not None else None if not pad or len(pad) < 24: return 0.0, 0.0, 0.0 fwd = -float(pad[PAD_AXIS_LY]) lat = -float(pad[PAD_AXIS_LX]) turn = float(pad[PAD_AXIS_RX]) return fwd, lat, turn
def walk_ik_step() -> None: """Called each tick by walk_forward / walk_back function JumpNode.""" if _bhv_commander is None: return walk = _bhv_commander.controller if walk is None: return fwd, _lat, turn = _pad_axes() walk_active = abs(fwd) >= STICK_DEAD _bhv_commander._variables['UserVal_0'] = 1 if walk_active else 0 if walk_active: walk.params.forward_stride = fwd * MAX_FWD_STRIDE walk.stride_turn_bias = ( turn * MAX_TURN_STRIDE if abs(turn) >= TURN_STICK_DEAD else 0.0 ) if walk.mot_sts != WalkController.WALK: walk.start_walk() walk.update_walking_state() walk.compute_walking_pose() walk.t += 1.0 / LOOP_HZ if walk.params.mix_enable: walk.apply_gyro_mixing(walk.data, _bhv_commander._imu) walk.data[28] = 1.0; walk.data[29] = -130.0 # l_elbow_yp override walk.data[58] = 1.0; walk.data[59] = -130.0 # r_elbow_yp override else: walk.stride_turn_bias = 0.0 if walk.mot_sts == WalkController.WALK: walk.stop()
def user_setup() -> None: if _bhv_commander is not None: ctrl = _bhv_commander.controller if ctrl is not None: ctrl.reset_pose() logger.info("Logic cartridge: ready (sample-style walk IK)")
def user_logic(r: list, s: list) -> list: pad_raw = _decode_meridim_pad(s) fwd = -pad_raw[PAD_AXIS_LY] lat = -pad_raw[PAD_AXIS_LX] turn = pad_raw[PAD_AXIS_RX] if _bhv_commander is not None: _bhv_commander._variables['UserVal_0'] = 1 if abs(fwd) >= STICK_DEAD else 0 _bhv_commander._variables['UserVal_2'] = 1 if abs(turn) >= TURN_STICK_DEAD else 0 _bhv_commander._variables['UserVal_3'] = 1 if abs(lat) >= SIDE_STICK_THRESH else 0 _bhv_commander.set_imu(r) _bhv_commander.set_pad(pad_raw) _bhv_commander.poll_and_update() return _bhv_commander.get_last_output() return list(s)
